create table if not exists public.v27_decision_runs (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,horizon_days integer not null default 14 check(horizon_days between 1 and 90),status text not null default 'running' check(status in ('running','completed','failed')),candidate_count integer not null default 0,recommended_count integer not null default 0,critical_positions integer not null default 0,projected_shortage_exposure numeric(24,8) not null default 0,started_at timestamptz not null default now(),completed_at timestamptz,created_by uuid references auth.users(id));
create table if not exists public.v27_decision_candidates (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,run_id uuid not null references public.v27_decision_runs(id) on delete cascade,location_id uuid not null references public.locations(id) on delete restrict,ingredient_id uuid not null references public.ingredients(id) on delete restrict,unit text not null,action_type text not null check(action_type in ('internal_transfer','expedite_inbound','secondary_supplier','recommended_supplier','no_action')),source_location_id uuid references public.locations(id) on delete restrict,supplier_id uuid references public.suppliers(id) on delete restrict,shipment_id uuid references public.v22_logistics_shipments(id) on delete restrict,quantity numeric(24,8) not null default 0 check(quantity>=0),action_lead_days numeric(24,8) not null default 0,projected_stock numeric(24,8) not null default 0,projected_rop numeric(24,8) not null default 0,projected_stockout_day integer,projected_rop_breach_day integer,projected_shortage_quantity numeric(24,8) not null default 0,projected_cost numeric(24,8) not null default 0,projected_expiry_exposure numeric(24,8) not null default 0,service_score numeric(8,4) not null default 0 check(service_score between 0 and 100),cost_score numeric(8,4) not null default 0 check(cost_score between 0 and 100),risk_score numeric(8,4) not null default 0 check(risk_score between 0 and 100),expiry_score numeric(8,4) not null default 0 check(expiry_score between 0 and 100),total_score numeric(8,4) not null default 0 check(total_score between 0 and 100),rank integer,recommendation_status text not null default 'candidate' check(recommendation_status in ('candidate','recommended','superseded','rejected')),rationale jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_v27_runs_business on public.v27_decision_runs(business_id,started_at desc); create index if not exists idx_v27_candidates_run on public.v27_decision_candidates(run_id,total_score desc);
alter table public.v27_decision_runs enable row level security; alter table public.v27_decision_candidates enable row level security;
drop policy if exists v27_runs_select on public.v27_decision_runs; create policy v27_runs_select on public.v27_decision_runs for select using(is_member(business_id));
drop policy if exists v27_candidates_select on public.v27_decision_candidates; create policy v27_candidates_select on public.v27_decision_candidates for select using(is_member(business_id));
revoke insert,update,delete on public.v27_decision_runs from authenticated; revoke insert,update,delete on public.v27_decision_candidates from authenticated;
create or replace view public.view_v27_latest_decisions with (security_invoker=true) as select c.*,l.code location_code,l.name location_name,i.name ingredient_name,sl.name source_location_name,su.name supplier_name,r.started_at run_started_at,r.horizon_days from public.v27_decision_candidates c join public.v27_decision_runs r on r.id=c.run_id join public.locations l on l.id=c.location_id join public.ingredients i on i.id=c.ingredient_id left join public.locations sl on sl.id=c.source_location_id left join public.suppliers su on su.id=c.supplier_id where r.status='completed' and r.started_at=(select max(r2.started_at) from public.v27_decision_runs r2 where r2.business_id=r.business_id and r2.status='completed');
create or replace function public.run_v27_decision_optimization(p_business_id uuid,p_horizon_days integer default 14) returns jsonb language plpgsql security definer set search_path=public as $$
declare run_id uuid; rec record; src record; sup record; qty numeric; stock numeric; rop numeric; demand numeric; lead numeric; shortage numeric; pstock numeric; cost numeric; ss numeric; risk numeric; service numeric; cscore numeric; rscore numeric; escore numeric; total numeric; n integer:=0; recommended integer:=0; critical integer:=0; exposure numeric:=0; supplier_unit_price numeric;
begin
 if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_horizon_days not between 1 and 90 then raise exception 'Horizon must be between 1 and 90 days'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_business_id::text,2700)); insert into public.v27_decision_runs(business_id,horizon_days,created_by) values(p_business_id,p_horizon_days,auth.uid()) returning id into run_id;
 for rec in select * from public.view_v20_location_reorder where business_id=p_business_id and not cold_start and below_rop and purchase_unit_exact order by greatest(0,reorder_point-current_stock) desc,location_id,ingredient_id loop
   stock:=greatest(0,coalesce(rec.current_stock,0)); rop:=greatest(0,coalesce(rec.reorder_point,0)); demand:=greatest(0,coalesce(rec.average_daily_demand,0)); lead:=greatest(0,coalesce(rec.lead_time_days,0)); ss:=greatest(0,coalesce(rec.safety_stock,0));
   for src in select s.location_id,s.current_stock,s.reorder_point,s.safety_stock,greatest(0,s.current_stock-s.reorder_point-s.safety_stock) available from public.view_v20_location_reorder s where s.business_id=p_business_id and s.ingredient_id=rec.ingredient_id and s.unit=rec.unit and s.location_id<>rec.location_id and not s.cold_start and s.purchase_unit_exact and s.current_stock>s.reorder_point+s.safety_stock order by greatest(0,s.current_stock-s.reorder_point-s.safety_stock) desc,s.location_id limit 3 loop
     qty:=least(greatest(rop-stock,0),src.available); if qty<=0 then continue; end if; pstock:=stock+qty; shortage:=greatest(0,demand*p_horizon_days-pstock); service:=least(100,greatest(0,100-shortage/greatest(demand*p_horizon_days,1)*100)); cscore:=100; rscore:=100; escore:=100; total:=round(service*.45+cscore*.25+rscore*.20+escore*.10,4);
     insert into public.v27_decision_candidates(business_id,run_id,location_id,ingredient_id,unit,action_type,source_location_id,quantity,action_lead_days,projected_stock,projected_rop,projected_shortage_quantity,service_score,cost_score,risk_score,expiry_score,total_score,rationale) values(p_business_id,run_id,rec.location_id,rec.ingredient_id,rec.unit,'internal_transfer',src.location_id,qty,0,pstock,rop,shortage,service,cscore,rscore,escore,total,jsonb_build_object('source_available',src.available)); n:=n+1;
   end loop;
   if rec.supplier_id is not null then
     qty:=greatest(rop-stock,0); select coalesce(t.lead_time_days,lead),coalesce(t.minimum_order_quantity,0),coalesce(t.order_multiple,0) into lead,ss,risk from public.supplier_ingredient_terms t where t.business_id=p_business_id and t.ingredient_id=rec.ingredient_id and t.supplier_id=rec.supplier_id and t.active and t.purchase_unit=rec.unit limit 1;
     if ss>0 then qty:=greatest(qty,ss); end if; if risk>0 then qty:=ceil(qty/risk)*risk; end if;
     if qty>0 then pstock:=stock+case when lead<=p_horizon_days then qty else 0 end; shortage:=greatest(0,demand*p_horizon_days-pstock); service:=least(100,greatest(0,100-shortage/greatest(demand*p_horizon_days,1)*100)); select coalesce(ip.purchase_price/ip.purchase_quantity/greatest(ip.usable_yield_fraction,0.00000001),0) into supplier_unit_price from public.ingredient_prices ip where ip.business_id=p_business_id and ip.ingredient_id=rec.ingredient_id and ip.supplier_id=rec.supplier_id order by ip.effective_from desc limit 1; cost:=qty*supplier_unit_price; cscore:=greatest(0,100-least(100,cost/greatest((rop+1)*greatest(supplier_unit_price,1),1)*100)); rscore:=greatest(0,100-coalesce((select risk_score from public.v23_supplier_risk_snapshots sr where sr.business_id=p_business_id and sr.supplier_id=rec.supplier_id),0)); escore:=100; total:=round(service*.45+cscore*.25+rscore*.20+escore*.10,4); insert into public.v27_decision_candidates(business_id,run_id,location_id,ingredient_id,unit,action_type,supplier_id,quantity,action_lead_days,projected_stock,projected_rop,projected_shortage_quantity,projected_cost,service_score,cost_score,risk_score,expiry_score,total_score,rationale) values(p_business_id,run_id,rec.location_id,rec.ingredient_id,rec.unit,'recommended_supplier',rec.supplier_id,qty,lead,pstock,rop,shortage,cost,service,cscore,rscore,escore,total,jsonb_build_object('lead_time_days',lead,'unit_price',supplier_unit_price)); n:=n+1; end if;
   end if;
   pstock:=stock; shortage:=greatest(0,demand*p_horizon_days-pstock); service:=least(100,greatest(0,100-shortage/greatest(demand*p_horizon_days,1)*100)); cscore:=100; rscore:=0; escore:=100; total:=round(service*.45+cscore*.25+rscore*.20+escore*.10,4);
   insert into public.v27_decision_candidates(business_id,run_id,location_id,ingredient_id,unit,action_type,quantity,projected_stock,projected_rop,projected_shortage_quantity,service_score,cost_score,risk_score,expiry_score,total_score,rationale) values(p_business_id,run_id,rec.location_id,rec.ingredient_id,rec.unit,'no_action',0,pstock,rop,shortage,service,cscore,rscore,escore,total,jsonb_build_object('baseline',true)); n:=n+1;
 end loop;
 with ranked as (select id,row_number() over(partition by location_id,ingredient_id,unit order by total_score desc,service_score desc,projected_cost asc,case action_type when 'internal_transfer' then 1 when 'recommended_supplier' then 2 else 3 end,id) rn from public.v27_decision_candidates where run_id=run_id) update public.v27_decision_candidates c set rank=ranked.rn,recommendation_status=case when ranked.rn=1 then 'recommended' else 'superseded' end from ranked where c.id=ranked.id;
 select count(*) into recommended from public.v27_decision_candidates where run_id=run_id and recommendation_status='recommended'; select count(*) into critical from public.v27_decision_candidates where run_id=run_id and recommendation_status='recommended' and projected_shortage_quantity>0; select coalesce(sum(projected_shortage_quantity),0) into exposure from public.v27_decision_candidates where run_id=run_id and recommendation_status='recommended'; update public.v27_decision_runs set status='completed',completed_at=now(),candidate_count=n,recommended_count=recommended,critical_positions=critical,projected_shortage_exposure=exposure where id=run_id; return jsonb_build_object('run_id',run_id,'candidate_count',n,'recommended_count',recommended,'critical_positions',critical,'projected_shortage_exposure',exposure);
exception when others then if run_id is not null then update public.v27_decision_runs set status='failed',completed_at=now() where id=run_id; end if; raise; end $$;
grant execute on function public.run_v27_decision_optimization(uuid,integer) to authenticated;
create or replace function public.v27_accept_decision(p_candidate_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare c record; begin select * into c from public.v27_decision_candidates where id=p_candidate_id for update; if c.id is null then raise exception 'Decision candidate not found'; end if; if not has_role(c.business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if c.recommendation_status<>'recommended' then raise exception 'Only recommended decisions can be accepted'; end if; insert into public.audit_logs(business_id,user_id,action,entity_type,entity_id,metadata) values(c.business_id,auth.uid(),'DecisionAccepted','v27_decision_candidate',c.id,jsonb_build_object('action_type',c.action_type,'quantity',c.quantity,'unit',c.unit,'total_score',c.total_score)); return jsonb_build_object('accepted',true,'candidate_id',c.id,'action_type',c.action_type,'quantity',c.quantity,'unit',c.unit); end $$;
grant execute on function public.v27_accept_decision(uuid) to authenticated;